 restoreWorld(){let m=this.mission;for(let t of MISSIONS[m.index].tasks)if(m.done.includes(t.id)){if(['flag','tripod','anchor','probe','beacon','relay'].includes(t.type))world.deploy(t,m.country);if(t.type==='pickup'){let o=world.taskObjects.get(t.id);if(o)o.visible=false}}if(m.flags.bridge)world.showBridge();if(m.hazardVersion)world.makeGrid(m.hazardVersion);for(let[k,p]of Object.entries(m.poses||{})){let a=k==='suit'?world.player:world[k];if(a){a.position.set(p.x,world.height(p.x,p.z)+(p.altitude||0),p.z);a.rotation.y=p.heading;a.userData.altitude=p.altitude}}if(m.payloadPose&&world.payload){let p=m.payloadPose;world.payload.position.set(p.x,world.height(p.x,p.z),p.z)}this.motion.follow=!!m.flags.follow;}
 snapshot(){let m=this.mission;if(this.page!=='world'||!m||this.exploration||m.complete||m.failed||!world.player)return;let poses={};for(let k of['suit','atlas','drone','alpha']){let a=k==='suit'?world.player:world[k];poses[k]={x:a.position.x,z:a.position.z,heading:a.rotation.y,altitude:k==='drone'?a.userData.altitude||.1:0}}m.poses=poses;if(world.payload)m.payloadPose={x:world.payload.position.x,z:world.payload.position.z};saved.active=JSON.parse(JSON.stringify({...m,paused:false}));persist()}
