 settings(){let s=saved.settings;modal('Experience settings','<div id="settings-fields"></div><p class="subtle">Outside sound is muted for a thin-atmosphere interpretation. Helmet mode uses authored suit/contact cues. Historical NASA audio is played separately.</p>',[['SAVE SETTINGS',()=>{for(let e of document.querySelectorAll('[data-setting]'))s[e.dataset.setting]=e.type==='range'?Number(e.value):e.value;audio.settings={...s};renderer.setPixelRatio(Math.min(devicePixelRatio,s.quality==='high'?1.5:s.quality==='balanced'?1:.75));renderer.shadowMap.enabled=s.quality!=='low';audio.applyMix();persist();closeModal()},true],['VR EXPLORATION',()=>{if(!navigator.xr){notify('WebXR unavailable in this browser');return}let b=VRButton.createButton(renderer);$('modal-actions').append(b)}]]);let fields=$('settings-fields');fields.innerHTML=`<label>GRAPHICS<select data-setting="quality"><option>high</option><option>balanced</option><option>low</option></select></label><label>AUDIO MODE<select data-setting="mode"><option>helmet</option><option>outside</option><option>cinematic</option></select></label>`;for(let k of['master','environment','vehicle','suit','ui','radio','music'])fields.innerHTML+=`<label>${k.toUpperCase()}<input data-setting="${k}" type="range" min="0" max="1" step=".05" value="${s[k]}"></label>`;for(let e of fields.querySelectorAll('select'))e.value=s[e.dataset.setting];}
