$('sound').onclick=async()=>{if(!audio.enabled){await audio.start();audio.settings={...saved.settings};$('sound').classList.add('selected')}else{audio.enabled=false;audio.suspend();$('sound').classList.remove('selected')}};
function openMap(){if(!app.mission)return;clearInput();app.mission.paused=true;$('map-overlay').classList.remove('hidden');app.drawMap($('map-large'),{span:520,routes:[app.guide],target:app.returning?{x:0,z:8}:app.task(),player:true});const active=app.task();$('map-explanation').textContent=`NEXT: ${goalDisplay(active)} · ${taskHint(active,app.mission)}. Cyan line = planned route. Cyan triangle = player. H = habitat. Orange ring = target. `+(app.guide?.stats?`${Math.round(app.guide.stats.meters)} m route · ${Math.ceil(app.guide.stats.seconds/60)} min estimated · ${world.stage<2?'NASA-derived terrain':'modeled terrain'}`:'No safe route found: backtrack or choose a different route.')}
function closeMap(){$('map-overlay').classList.add('hidden');if(app.mission)app.mission.paused=false;clearInput()}
$('guide-button').onclick=()=>{const t=app.task(),m=app.mission;if(!t||!m)return;modal('How to complete this mission',`<p><b>Current target:</b> ${esc(goalDisplay(t))}</p><p>${esc(taskHint(t,m))}</p><p>1. Follow the cyan route and orange TARGET marker on the upper-right minimap. Your current position is the cyan triangle.</p><p>2. On arrival, use INTERACT (E) or the indicated tool/vehicle to perform the objective. Some tools require holding E, aligning with arrow keys or using mouse drag.</p><p>3. Your next objective appears automatically. Press MAP (M) at any point for a larger route map. You can switch to a lower-risk route there.</p><p>4. After all tasks, follow the route marked H back to the habitat. Walk inside the landing zone; mission completes automatically and the next stage unlocks.</p><p>Controls: WASD / right joystick move · mouse drag rotate · Shift run · Space jump · R change robot · M map · Esc pause.</p>${presenterMode?'<p><b>LOCAL PRESENTER MODE:</b> All ten stages are selectable for recording; normal player progress stays separate. This is not an online admin login.</p>':''}`,[['SHOW MAP',()=>{closeModal();openMap()},true],['CONTINUE PLAYING',closeModal]]);};
$('map-button').onclick=openMap;$('map-close').onclick=closeMap;$('safe-route').onclick=()=>{app.routeMode='safe';app.returning=false;app.refreshGuide(true);openMap()};$('direct-route').onclick=()=>{app.routeMode='fast';app.returning=false;app.refreshGuide(true);openMap()};$('return-route').onclick=()=>{closeMap();app.emergencyPlan(app.task()?.type==='replan')};
$('region').onchange=()=>app.prepareScience('atlas');$('layer').onchange=()=>app.drawScience();$('route-region').onchange=()=>app.prepareScience('ops');$('route-target').onchange=()=>{app.target=({north:{x:0,z:-120},east:{x:100,z:-70},west:{x:-110,z:-80}})[$('route-target').value]||app.target;app.invalidateOps();app.drawScience()};for(let id of ['eva-budget','reserve-budget','oxygen-budget','energy-budget','radiation-budget'])$(id).oninput=()=>app.invalidateOps();$('ops-demo').onclick=()=>{app.opHazard=1;$('route-target').value='north';app.calculateOps()};$('calculate').onclick=()=>app.calculateOps();$('execute').onclick=()=>{if(app.plan?.budget.feasible)app.explore(true)};$('ops-emergency').onclick=()=>{app.opHazard++;world.makeGrid(app.opHazard);app.calculateOps()};$('sources').onclick=()=>app.sourceDetails();$('ops-sources').onclick=()=>app.sourceDetails();$('nasa-evidence').onclick=()=>app.nasaEvidence();$('explore').onclick=()=>app.explore();
