$('export-save').onclick=()=>{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(saved,null,2)],{type:'application/json'}));a.download='ARES_PATHFINDER_SAVE.json';a.click();URL.revokeObjectURL(a.href)};$('import-save').onchange=async e=>{try{let raw=JSON.parse(await e.target.files[0].text());if(raw.version!==3)throw Error('Save version mismatch');Object.assign(saved,validateSave(raw));persist();app.renderProfile()}catch(err){modal('Save import rejected','<p>'+esc(err.message)+'</p>',[['CLOSE',closeModal]])}};
window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys.add(k);if(e.repeat)return;if(k==='escape'){if(app.modalOpen)closeModal();else app.pause()}if(app.page!=='world'||app.modalOpen)return;if(k==='e')app.interact();if(k==='r')app.vehicleMenu();if(k==='m')openMap();if(k===' ')jumpEdge=true;if(k==='c')$('slide-button').click();if(k==='h')app.heaterMenu();if(k==='t'){app.mission.traction=!app.mission.traction;notify('Traction '+(app.mission.traction?'ON':'OFF'))}if(k==='f'){app.motion.follow=!app.motion.follow;app.mission.flags.follow=app.motion.follow;notify(app.motion.follow?'Robots following leader':'Robots holding position')}if(k==='b')app.useBattery();if(['1','2','3','4'].includes(k))app.switchMode(['suit','atlas','drone','alpha'][+k-1]);});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{clearInput();if(app.page==='world'&&!qaMode&&!app.modalOpen)app.pause()});
let joyPointer=null;const joystick=$('joystick');function updateJoy(e){let r=joystick.getBoundingClientRect(),radius=r.width/2,x=(e.clientX-r.left-radius)/radius,y=(e.clientY-r.top-radius)/radius,len=Math.max(1,Math.hypot(x,y));joy={x:x/len,y:-y/len};$('knob').style.transform=`translate(${joy.x*radius*.48}px,${-joy.y*radius*.48}px)`}joystick.onpointerdown=e=>{joyPointer=e.pointerId;joystick.setPointerCapture(joyPointer);updateJoy(e)};joystick.onpointermove=e=>{if(e.pointerId===joyPointer)updateJoy(e)};for(let ev of['pointerup','pointercancel'])joystick.addEventListener(ev,()=>{joyPointer=null;joy={x:0,y:0};$('knob').style.transform='translate(0,0)'});
renderer.domElement.onpointerdown=e=>{if(app.page==='world'){drag={id:e.pointerId,x:e.clientX,y:e.clientY};renderer.domElement.setPointerCapture(e.pointerId)}};renderer.domElement.onpointermove=e=>{if(!drag||drag.id!==e.pointerId)return;let dx=e.clientX-drag.x,dy=e.clientY-drag.y;drag.x=e.clientX;drag.y=e.clientY;if(app.tool){app.tool.aim.x=clamp(app.tool.aim.x+dx*.002,-.75,.75);app.tool.aim.y=clamp(app.tool.aim.y-dy*.002,-.75,.75)}else{app.yaw-=dx*.004;app.pitch=clamp(app.pitch+dy*.004,-.05,1.05)}};renderer.domElement.onpointerup=()=>drag=null;renderer.domElement.onpointercancel=()=>drag=null;renderer.domElement.onwheel=e=>{if(app.page==='world')app.cameraDistance=clamp(app.cameraDistance+e.deltaY*.008,3.2,14)};
