window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});window.addEventListener('beforeunload',()=>app.snapshot());let prev=performance.now(),nextMini=0;
renderer.setAnimationLoop(time=>{let raw=(time-prev)/1000,dt=Math.min(.05,Math.max(0,raw));prev=time;if(!app.worldReady)return;app.elapsed+=dt;if(app.frameTimes.length<600)app.frameTimes.push(raw);if(!app.qaDriving){app.step(dt,input());jumpEdge=false}if(app.page==='home'){world.atlas.position.set(-2.8+Math.sin(time*.0002)*.35,world.height(-2.8,-14),-14);world.atlas.rotation.y=-.5;app.homeCamera()}if(app.page==='world')app.updateCamera(dt);let pos=app.page==='world'&&app.mission?app.actor().position:null;world.animate(dt,time*.001,app.page==='home',pos);if(audio.enabled)audio.listener(camera);if(audio.enabled&&app.mission&&app.page==='world'&&world.player&&Math.floor(time/500)!==app.lastSpatial){app.lastSpatial=Math.floor(time/500);if(Math.abs(world.atlas.userData.speed||0)>.1)audio.spatial('rover',world.atlas.position,.15);if(world.drone.position.y-world.height(world.drone.position.x,world.drone.position.z)>1)audio.spatial('drone',world.drone.position,.1)}if(audio.enabled&&app.mission&&app.page==='world'&&world.player)audio.update?.({stage:app.mission.index,rover:app.mission.mode==='atlas',moving:Math.abs(app.actor()?.userData.speed||0)>.1,storm:world.dust,playerX:world.player.position.x,roverX:world.atlas.position.x,distance:world.atlas.position.distanceTo(world.player.position),oxygen:app.mission.oxygen});if(time>nextMini&&app.page==='world'){let p=app.actor().position;const target=app.returning?{x:0,z:8}:app.task();const targetDistance=target?Math.hypot(p.x-target.x,p.z-target.z):0;app.drawMap($('mini'),{center:{x:p.x,z:p.z},span:Math.max(160,Math.min(750,targetDistance*2.65)),routes:[app.guide],target,player:true});$('heading').textContent=['N','NE','E','SE','S','SW','W','NW'][((Math.round(-app.yaw/(Math.PI/4))%8)+8)%8];nextMini=time+250}renderer.render(scene,camera)});
